  void (APIENTRY *glDisableVertexAttribArray)(jint);
  void (APIENTRY *glCopyTexSubImage2D)(jint, jint, jint, jint, jint, jint, jint, jint);
  void (APIENTRY *glFramebufferTexture2D)(jint, jint, jint, jint, jint);
